namespace ghidra.app.plugin.core.codebrowser.hover;




using docking.widgets.fieldpanel.field;
using docking.widgets.fieldpanel.support;
using ghidra;
using ghidra.app.plugin.core.hover;
using ghidra.app.util.viewer.field;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.util;

/**
 * A hover service to show tool tip text for hovering over a truncated field, containing a "...",
 * in the listing.
 * The tooltip shows the entire text for that field.
 * This provides the hover capability for the TruncatedTextHoverPlugin and can
 * also be used to directly provide this hover capability to a listing.
 */
public class TruncatedTextListingHover : AbstractConfigurableHover, ListingHoverService {

	private static readonly string NAME = "Truncated Text Display";
	private static readonly string DESCRIPTION =
		"Toggle whether truncated text is displayed in a tooltip " +
			"when the mouse hovers over a field that is truncated.";
	private static readonly int POPUP_PRIORITY = 10;

	public TruncatedTextListingHover(PluginTool tool) : base(tool, POPUP_PRIORITY)
    {
	}

	/* @Override */
	protected string getName() {
		return NAME;
	}

	/* @Override */
	protected string getDescription() {
		return DESCRIPTION;
	}

	/* @Override */
	protected string getOptionsCategory() {
		return GhidraOptions.CATEGORY_BROWSER_POPUPS;
	}

	/* @Override */
	public JComponent getHoverComponent(Program program, ProgramLocation programLocation,
			FieldLocation fieldLocation, Field field) {

		if (!enabled || programLocation == null || !(field is ListingTextField)) {
			return null;
		}

		if (((ListingTextField) field).isClipped()) {
			string text = field.getTextWithLineSeparators();
			string convertToHtml = HTMLUtilities.toLiteralHTMLForTooltip(text);
			JToolTip toolTip = new JToolTip();
			toolTip.setTipText(convertToHtml);
			return toolTip;
		}

		return null;
	}
}
